use std::{path::Path,process::{Child,Command,ExitStatus,Stdio},io::{Read,Write}};
use ao_reason_workbench::core::store::Run;
use serde_json::{Value,json};
fn config(t:&tempfile::TempDir)->std::path::PathBuf {std::fs::write(t.path().join("B.key"),"09".repeat(32)).unwrap();let p=t.path().join("config.json");std::fs::write(&p,serde_json::to_vec(&json!({"schema":"ao-reason-config/1","mode":"local","role":"controller","deployment":"mcp-test","state_dir":"state","nodes":[{"id":"B","address":"local-B/runner","key_file":"B.key","slots":1,"templates":["sum-native-v1"],"admitted":true,"healthy":true}]})).unwrap()).unwrap();p}
fn invoke(p:&std::path::Path,host:bool,requests:&[Value])->Vec<Value>{let mut c=Command::new(env!("CARGO_BIN_EXE_aw-cli"));c.args(["mcp","--config"]).arg(p).env_remove("AO_SESSION_ID").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());if host{c.env("AO_SESSION_ID","synthetic-host-session");}let mut child=c.spawn().unwrap();{let mut stdin=child.stdin.take().unwrap();for request in requests{writeln!(stdin,"{}",request).unwrap();}}let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));String::from_utf8(output.stdout).unwrap().lines().map(|s|serde_json::from_str(s).unwrap()).collect()}
fn persisted_runs(state:&Path)->Vec<Run>{let db=rusqlite::Connection::open(state.join("controller.sqlite")).unwrap();let mut stmt=db.prepare("SELECT body FROM runs ORDER BY seq").unwrap();stmt.query_map([],|row|row.get::<_,String>(0)).unwrap().map(|row|serde_json::from_str(&row.unwrap()).unwrap()).collect()}
fn assert_uncertain_run(run:&Run){assert_eq!(run.status,"unknown");assert_eq!(run.detail["report"]["sum"],6);assert_eq!(run.detail["verification"]["state"],"owner_evidence_required");assert!(run.detail["verification"]["passed"].is_null());}
fn assert_assignment_retained(state:&Path,run_id:&str){let db=rusqlite::Connection::open(state.join("controller.sqlite")).unwrap();let released:i64=db.query_row("SELECT released FROM assignments WHERE run=?1 AND attempt=1",[run_id],|row|row.get(0)).unwrap();assert_eq!(released,0,"ordinary observer proof must retain assignment");}
fn preserve_fixture(t:tempfile::TempDir)->std::path::PathBuf{t.keep()}
fn controller_diagnostic(child:&mut Child,t:tempfile::TempDir,status:ExitStatus)->!{let fixture=preserve_fixture(t);let mut stderr=Vec::new();if let Some(mut pipe)=child.stderr.take(){pipe.read_to_end(&mut stderr).expect("read controller stderr");}panic!("controller exited unexpectedly: status={status:?} code={:?} stderr={} fixture_path={}",status.code(),String::from_utf8_lossy(&stderr),fixture.display())}
#[test]
fn stdio_mcp_initializes_lists_seven_and_dispatches_as_host_bound_actor(){let t=tempfile::tempdir().unwrap();let p=config(&t);let replies=invoke(&p,true,&[json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-11-25"}}),json!({"jsonrpc":"2.0","method":"notifications/initialized"}),json!({"jsonrpc":"2.0","id":2,"method":"tools/list"}),json!({"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"dispatch","arguments":{"template":"sum-native-v1"}}})]);assert_eq!(replies.len(),3);assert_eq!(replies[0]["result"]["protocolVersion"],"2025-11-25");assert_eq!(replies[1]["result"]["tools"].as_array().unwrap().len(),7);assert_eq!(replies[1]["result"]["tools"][0]["inputSchema"]["additionalProperties"],false);let run:Value=serde_json::from_str(replies[2]["result"]["content"][0]["text"].as_str().unwrap()).unwrap();assert_eq!(run["status"],"queued");assert_eq!(run["owner"],json!({"kind":"ao_session","id":"synthetic-host-session"}));}
#[test]
fn missing_host_never_fabricates_actor_or_accepts_owner_argument(){let t=tempfile::tempdir().unwrap();let p=config(&t);let r=invoke(&p,false,&[json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"dispatch","arguments":{"template":"sum-native-v1","owner":"fake"}}})]);assert_eq!(r[0]["result"]["isError"],true);}
#[test]
fn native_cli_local_check_preserves_uncertain_observer_result(){let t=tempfile::tempdir().unwrap();let state=t.path().join("native");let output=Command::new(env!("CARGO_BIN_EXE_aw-cli")).args(["local-check","--state-dir"]).arg(&state).output().unwrap();assert!(!output.status.success());assert!(String::from_utf8_lossy(&output.stderr).contains("uncertain task remains in ledger"));let runs=persisted_runs(&state);assert_eq!(runs.len(),1);assert_uncertain_run(&runs[0]);assert_assignment_retained(&state,&runs[0].id);}
#[test]
fn repeated_local_check_dispatches_new_run_without_reusing_historical_unknown(){let t=tempfile::tempdir().unwrap();let state=t.path().join("native");let run=||{let output=Command::new(env!("CARGO_BIN_EXE_aw-cli")).args(["local-check","--state-dir"]).arg(&state).output().unwrap();assert!(!output.status.success());assert!(String::from_utf8_lossy(&output.stderr).contains("uncertain task remains in ledger"));};run();run();let runs=persisted_runs(&state);assert_eq!(runs.len(),2);assert_uncertain_run(&runs[0]);assert_assignment_retained(&state,&runs[0].id);assert_eq!(runs[1].status,"queued","new dispatch must not be reported as historical completion when the prior reservation remains held");}
#[test]
fn check_does_not_start_service_and_controller_once_opens_explicit_local_ledger(){let t=tempfile::tempdir().unwrap();let p=config(&t);let out=Command::new(env!("CARGO_BIN_EXE_aw-cli")).args(["check","--config"]).arg(&p).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let v:Value=serde_json::from_slice(&out.stdout).unwrap();assert_eq!(v["configuration_valid"],true);assert_eq!(v["active_probe"],false);assert!(!t.path().join("state").exists());let out=Command::new(env!("CARGO_BIN_EXE_aw-cli")).args(["controller","--config"]).arg(&p).arg("--once").output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));assert!(t.path().join("state/controller.sqlite").is_file());assert!(t.path().join("state/runner.sqlite").is_file());}
#[test]
fn headless_controller_completes_mcp_dispatched_native_fixture(){let t=tempfile::tempdir().unwrap();let p=config(&t);let r=invoke(&p,true,&[json!({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"dispatch","arguments":{"template":"sum-native-v1"}}})]);let dispatched:Value=serde_json::from_str(r[0]["result"]["content"][0]["text"].as_str().unwrap()).unwrap();let id=dispatched["id"].as_str().unwrap();struct Owned(std::process::Child);impl Drop for Owned{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}let mut child=Owned(Command::new(env!("CARGO_BIN_EXE_aw-cli")).args(["controller","--config"]).arg(&p).stdout(Stdio::null()).stderr(Stdio::piped()).spawn().unwrap());let deadline=std::time::Instant::now()+std::time::Duration::from_secs(15);loop{if let Some(status)=child.0.try_wait().unwrap(){controller_diagnostic(&mut child.0,t,status)}let r=invoke(&p,true,&[json!({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"status","arguments":{"run_id":id}}})]);let status:Value=serde_json::from_str(r[0]["result"]["content"][0]["text"].as_str().unwrap()).unwrap();if status["status"]=="unknown"{assert_eq!(status["detail"]["report"]["sum"],6);assert_eq!(status["detail"]["verification"]["state"],"owner_evidence_required");assert!(status["detail"]["verification"]["passed"].is_null());break}assert!(std::time::Instant::now()<deadline,"controller failed to reach owner-admission-gated terminal observation: {status}");std::thread::sleep(std::time::Duration::from_millis(20));}}
